<style>.section-label{color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.3em;text-transform:uppercase}.event-layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:28px;align-items:start}.event-cover{overflow:hidden;margin-bottom:24px;border-radius:27px}.event-cover img{display:block;width:100%;height:auto}.event-copy{padding:30px;border:1px solid var(--border);border-radius:26px;background:#fff;color:var(--muted-foreground);line-height:1.75}.event-facts{position:sticky;top:105px;padding:28px;border-radius:26px;background:var(--gradient-cool)}.event-facts p{padding-bottom:14px;border-bottom:1px solid var(--border)}.registration{margin-top:28px;padding:32px;border:1px solid var(--border);border-radius:27px;background:#fff}.registration h2{font-size:28px}.registration .btn{margin-top:18px;border:0;cursor:pointer}.closed{margin-top:26px;padding:18px 22px;border-radius:18px;background:var(--muted);font-weight:700}@media(max-width:820px){.event-layout{grid-template-columns:1fr}.event-facts{position:static}}</style>
