<?php if($open): ?><div class="registration"><span class="section-label">Partecipa</span><h2>Iscriviti all’evento</h2><form method="post" action="<?= $event['audience']==='cat'?'/idemaclima/campus/cat/':'/idemaclima/campus/' ?><?= e($event['slug']) ?>/iscrizione"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><div style="position:absolute;left:-10000px;top:auto;width:1px;height:1px;overflow:hidden" aria-hidden="true"><label>Sito web aziendale<input name="company_website" tabindex="-1" autocomplete="off"></label></div><div class="formgrid"><label>Nome<input name="first_name" maxlength="120" required value="<?= e($catUser['contact_first_name']??'') ?>"></label><label>Cognome<input name="last_name" maxlength="120" required value="<?= e($catUser['contact_last_name']??'') ?>"></label><label>Email<input type="email" maxlength="190" name="email" required value="<?= e($catUser['email']??'') ?>"></label><label>Telefono<input name="phone" maxlength="50" value="<?= e($catUser['phone']??'') ?>"></label><label>Azienda<input name="company" maxlength="190" value="<?= e($catUser['company_name']??'') ?>"></label><label>Ruolo<input name="role" maxlength="120"></label><label class="full">Note<textarea name="notes" maxlength="4000"></textarea></label><label class="full check"><input type="checkbox" name="privacy" value="1" required> Accetto l’informativa privacy</label></div><button class="btn" type="submit">Invia iscrizione</button></form></div><?php else:?><div class="closed">Iscrizioni chiuse.</div><?php endif; ?>
